// ColorTwist family executor (nppiColorTwist*, nppiColorTwist32f*, batch).
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_color_twist_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_color_twist*.json).
//
// Semantics (baseline NVIDIA NPP 13.4, pinned by the differential tests in
// test/unit/diff/test_nppi_color_twist*_generated.cpp):
//   * 3x4 twist: out_c = sum_j aTwist[c][j] * in_j + aTwist[c][3] for the first
//     min(channels, 3) output channels; in_j for j >= channels reads as 0
//     (measured; no channel replication).
//   * C4 (packed, non-AC4): the alpha channel is copied bit-exact from the
//     source.  AC4: the alpha channel is neither read nor written.
//   * P3/IP3: planar 3-channel variant of the same math, no rounding bias.
//   * rounding bias: the packed CH>=3 kernels add +0.5f to the accumulated
//     value.  Npp32f keeps it in the output; integer dtypes combine it with a
//     truncate-toward-zero conversion (round half up) and saturate to the
//     dtype range; C1/C2 packed, planar and all Npp16f variants have no bias
//     (Npp16f converts with round-to-nearest).
//   * "C" variants (nppiColorTwist32fC / nppiColorTwist_32fC): full 4x4 twist
//     plus a per-channel additive constant, applied to all four channels
//     (alpha is computed from the 4th matrix row, never copied).  The rounding
//     rules match the packed 3x4 path: Npp8u adds the +0.5f bias with the
//     truncate conversion, Npp32f keeps the bias in the output, Npp16f has no
//     bias and converts round-to-nearest.
//   * Batch variants: every NppiColorTwistBatchCXR entry carries its own twist
//     matrix (12 floats, or 20 floats = 4x4 + 4 constants for the "C" forms).
//     Measured on the RTX 5090:
//     - the +0.5f bias is applied FIRST, then out = clamp(acc + 0.5f, nMin,
//       nMax), then the dtype conversion (an inverted [nMin, nMax] range
//       yields nMax); Npp32f is biased on EVERY layout (even C1), integer
//       dtypes only for CH >= 3, Npp16f never.  The clamp is comparison-based,
//       so a NaN produced by the dot product (0 * +-inf) survives it.
//     - Npp8u conversion: the LOW BYTE of (Npp8u)__float2uint_rz(x) - no
//       [0,255] saturation (values past 255 wrap, negatives become 0), unlike
//       every non-batch kernel.  Npp16f / Npp32f convert as usual.
//     - the non-const C4/AC4 batch kernels never twist alpha: Npp8u/Npp32f
//       leave the destination alpha untouched, Npp16f COPIES the source alpha
//       (unlike the single-image C4 of every dtype, which copies it); the "C"
//       batch forms compute alpha from the 4th matrix row + constant like the
//       "C" single-image forms (clamped and low-byte converted).
//     - the AC4 batch kernels exempt output channel 2 from the [nMin, nMax]
//       clamp and convert it with the saturating [0,255] conversion instead
//       (both sides measured: 32f identity for the min side, 8u twist3b for
//       the max side); channels 0/1 clamp normally.
//     - validation: null list -> NPP_NULL_POINTER_ERROR; nBatchSize < 2 ->
//       NPP_BAD_ARGUMENT_ERROR ("must be > 1" is enforced); negative ROI ->
//       NPP_SIZE_ERROR; an empty ROI launches a degenerate grid and returns
//       NPP_CUDA_KERNEL_EXECUTION_ERROR.  Steps and per-entry pointers are
//       NOT validated: a null entry pointer returns NPP_NO_ERROR and faults
//       on the device, a misaligned src step faults; negative steps are
//       unspecified (not measurable without faulting the reference), mcMPP
//       defensively skips those entries.
//   * validation (measured): negative ROI -> NPP_SIZE_ERROR; packed dst step
//     uses an unsigned range check (0 <= step < rowBytes -> NPP_STEP_ERROR,
//     negative accepted); the packed src step is not validated; planar
//     variants check both steps signed; null pointers -> NPP_NULL_POINTER_
//     ERROR; an empty ROI returns NPP_NO_ERROR before the even-step check.
//     After those checks the destination steps must be a multiple of the
//     vector width (2 elements for C2, 4 for C4/AC4, one element for C1/C3
//     and the planar variants; the planar src step is checked too) or
//     NPP_NOT_EVEN_STEP_ERROR is returned (signed modulo: an even negative
//     step keeps the accepted-no-launch behavior).  A null aTwist / null
//     planar array crashes the NVIDIA reference; mcMPP returns
//     NPP_NULL_POINTER_ERROR instead.
#ifndef NPPI_COLOR_TWIST_EXECUTOR_H
#define NPPI_COLOR_TWIST_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace colortwist {

// --- 3x4 twist, packed layouts ----------------------------------------------

// Not in-place (C1R/C2R/C3R/C4R/AC4R).  Channels: 1..4; AlphaPreserve selects
// the AC4 layout (4 channels, alpha untouched).
template <typename T, int Channels, bool AlphaPreserve>
NppStatus twistR(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, NppiSize oSizeROI, const Npp32f aTwist[3][4],
                 cudaStream_t stream);

// In-place (C1IR/.../C4IR/AC4IR).
template <typename T, int Channels, bool AlphaPreserve>
NppStatus twistIR(T *pSrcDst, int nSrcDstStep, NppiSize oSizeROI, const Npp32f aTwist[3][4], cudaStream_t stream);

// --- 3x4 twist, planar layouts ----------------------------------------------

template <typename T>
NppStatus twistP3(const T *const pSrc[3], int nSrcStep, T *const pDst[3], int nDstStep, NppiSize oSizeROI,
                  const Npp32f aTwist[3][4], cudaStream_t stream);

template <typename T>
NppStatus twistIP3(T *const pSrcDst[3], int nSrcDstStep, NppiSize oSizeROI, const Npp32f aTwist[3][4],
                   cudaStream_t stream);

// --- 4x4 twist + additive constants ("C" variants, 4 packed channels) --------

template <typename T>
NppStatus twistCR(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, NppiSize oSizeROI, const Npp32f aTwist[4][4],
                  const Npp32f aConstants[4], cudaStream_t stream);

template <typename T>
NppStatus twistCIR(T *pSrcDst, int nSrcDstStep, NppiSize oSizeROI, const Npp32f aTwist[4][4],
                   const Npp32f aConstants[4], cudaStream_t stream);

// --- batch (single ROI for every entry, per-entry twist matrix) --------------

// WithConstants selects the 4x4 + 4 constants matrix layout (the "C" batch
// forms); otherwise the twist matrix is 3x4.  InPlace selects the IR forms.
template <typename T, int Channels, bool AlphaPreserve, bool InPlace, bool WithConstants>
NppStatus batchTwist(Npp32f nMin, Npp32f nMax, NppiSize oSizeROI, NppiColorTwistBatchCXR *pBatchList, int nBatchSize,
                     cudaStream_t stream);

}  // namespace colortwist
}  // namespace nppi

#endif  // NPPI_COLOR_TWIST_EXECUTOR_H
